// lib/motion.ts
// -----------------------------------------------------------------------------
// LENGUAJE DE MOVIMIENTO — Yeti BI
// Fuente única de verdad para todas las animaciones del sitio.
// Toda sección debe reusar estos tokens y variantes para que el movimiento
// se sienta coherente en TODA la web, no inventado pedazo por pedazo.
//
// Accesibilidad: NO se gestiona prefers-reduced-motion aquí. Envuelve tu layout
// raíz una sola vez en <MotionConfig reducedMotion="user"> y Motion desactiva
// automáticamente las animaciones de transform/opacity para quien lo pida.
// Ejemplo en app/layout.tsx:
//   import { MotionConfig } from "motion/react";
//   <MotionConfig reducedMotion="user">{children}</MotionConfig>
// -----------------------------------------------------------------------------

import {
  type Variants,
  type Transition,
  animate,
  useInView,
  useScroll,
  useTransform,
} from "motion/react";
import { useEffect, useRef, useState } from "react";

// -----------------------------------------------------------------------------
// 1. TOKENS — calibra aquí UNA vez y todo el sitio respira igual
// -----------------------------------------------------------------------------
export const motionTokens = {
  duration: {
    fast: 0.4, // microinteracciones
    base: 0.6, // reveals de sección (el workhorse)
    slow: 0.8, // bloques grandes
    hero: 0.9, // entrada del hero
  },
  // "expo-out": arranca rápido y desacelera suave -> sensación premium
  ease: {
    out: [0.22, 1, 0.36, 1] as [number, number, number, number],
    inOut: [0.65, 0, 0.35, 1] as [number, number, number, number],
  },
  distance: {
    sm: 16, // textos pequeños
    md: 24, // tarjetas, párrafos
    lg: 40, // bloques destacados
  },
  stagger: {
    tight: 0.08, // listas densas (logos, cifras)
    base: 0.12, // grilla de servicios
    loose: 0.18, // pasos de metodología (más teatral)
  },
};

// -----------------------------------------------------------------------------
// 2. TRANSICIONES base reutilizables
// -----------------------------------------------------------------------------
export const baseTransition: Transition = {
  duration: motionTokens.duration.base,
  ease: motionTokens.ease.out,
};

export const heroTransition: Transition = {
  duration: motionTokens.duration.hero,
  ease: motionTokens.ease.out,
};

// Spring suave para hovers — mismo "peso" en todas las tarjetas del sitio
export const softSpring: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 25,
};

// -----------------------------------------------------------------------------
// 3. VARIANTES — el vocabulario de entrada
//    Patrón: el padre usa staggerContainer, los hijos usan fadeUp/scaleIn.
// -----------------------------------------------------------------------------

// Fade + desplazamiento hacia arriba. La variante que más vas a usar.
export const fadeUp: Variants = {
  hidden: { opacity: 0, y: motionTokens.distance.md },
  show: { opacity: 1, y: 0, transition: baseTransition },
};

// Variante "chica" para subtítulos / textos secundarios
export const fadeUpSm: Variants = {
  hidden: { opacity: 0, y: motionTokens.distance.sm },
  show: { opacity: 1, y: 0, transition: baseTransition },
};

// Solo opacidad (fondos, imágenes de hero)
export const fadeIn: Variants = {
  hidden: { opacity: 0 },
  show: { opacity: 1, transition: { duration: motionTokens.duration.slow, ease: motionTokens.ease.out } },
};

// Escala + fade — ideal para tarjetas de servicio
export const scaleIn: Variants = {
  hidden: { opacity: 0, scale: 0.96, y: motionTokens.distance.sm },
  show: { opacity: 1, scale: 1, y: 0, transition: baseTransition },
};

// -----------------------------------------------------------------------------
// 4. CONTENEDORES con stagger — orquestan la entrada de los hijos
//    Factory para poder ajustar el ritmo por sección sin duplicar código.
// -----------------------------------------------------------------------------
export const staggerContainer = (
  stagger: number = motionTokens.stagger.base,
  delayChildren: number = 0
): Variants => ({
  hidden: {},
  show: {
    transition: { staggerChildren: stagger, delayChildren },
  },
});

// Atajos nombrados para los casos del brief
export const heroContainer = staggerContainer(motionTokens.stagger.base, 0.1);
export const servicesContainer = staggerContainer(motionTokens.stagger.base);
export const methodologyContainer = staggerContainer(motionTokens.stagger.loose);
export const statsContainer = staggerContainer(motionTokens.stagger.tight);

// -----------------------------------------------------------------------------
// 5. CONFIGS DE INTERACCIÓN — hover de tarjetas con glow naranja de marca
//    Uso: <motion.div {...cardHover}> ... </motion.div>
// -----------------------------------------------------------------------------
export const cardHover = {
  whileHover: {
    y: -6,
    boxShadow: "0 20px 40px -12px rgba(224, 123, 48, 0.35)", // #E07B30 difuso
    transition: softSpring,
  },
  whileTap: { scale: 0.98 },
};

// -----------------------------------------------------------------------------
// 6. PRESET DE VIEWPORT para reveals al hacer scroll (whileInView)
//    Uso: <motion.section variants={...} initial="hidden" whileInView="show" viewport={revealViewport}>
// -----------------------------------------------------------------------------
export const revealViewport = { once: true, amount: 0.25 };

// -----------------------------------------------------------------------------
// 7. HOOK: count-up animado para el bloque de CIFRAS
//    Dispara solo cuando el elemento está ~40% visible. Devuelve el ref que
//    montas en el contenedor y el número ya formateado con separador de miles.
//    Uso:
//      const { ref, display } = useCountUp(10000, { suffix: "+" });
//      <span ref={ref}>{display}</span>
// -----------------------------------------------------------------------------
type CountUpOptions = {
  duration?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  locale?: string;
};

export function useCountUp(target: number, options: CountUpOptions = {}) {
  const {
    duration = 1.5,
    decimals = 0,
    prefix = "",
    suffix = "",
    locale = "es-CO",
  } = options;

  const ref = useRef<HTMLElement | null>(null);
  const inView = useInView(ref, { once: true, amount: 0.4 });
  const [value, setValue] = useState(0);

  useEffect(() => {
    if (!inView) return;
    const controls = animate(0, target, {
      duration,
      ease: motionTokens.ease.out,
      onUpdate: (v) => setValue(v),
    });
    return () => controls.stop();
  }, [inView, target, duration]);

  const display =
    prefix +
    value.toLocaleString(locale, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }) +
    suffix;

  return { ref, value, display };
}

// -----------------------------------------------------------------------------
// 8. HOOK: parallax sutil para el fondo del HERO
//    Uso:
//      const { ref, y } = useParallax(60);
//      <section ref={ref}><motion.div style={{ y }}>...fondo...</motion.div></section>
// -----------------------------------------------------------------------------
export function useParallax(distance: number = 60) {
  const ref = useRef<HTMLElement | null>(null);
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start start", "end start"],
  });
  const y = useTransform(scrollYProgress, [0, 1], [0, distance]);
  return { ref, y };
}
