'use client'

import { useState, useEffect } from 'react'
import { motion } from 'motion/react'
import Link from 'next/link'

export function Navigation() {
  const [isScrolled, setIsScrolled] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 24)
    }
    window.addEventListener('scroll', handleScroll, { passive: true })
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  const navLinks = [
    { href: '#problema', label: 'El problema' },
    { href: '#servicios', label: 'Servicios' },
    { href: '#metodologia', label: 'Metodología' },
    { href: '#resultados', label: 'Resultados' },
  ]

  return (
    <>
      <nav
        className={`fixed top-0 inset-x-0 z-50 flex items-center justify-between gap-6 px-6 md:px-8 py-4 transition-all duration-300 ${
          isScrolled
            ? 'bg-[#2E2640]/82 backdrop-blur-[18px] border-b border-white/10'
            : 'bg-transparent'
        }`}
      >
        {/* Brand */}
        <Link href="#" className="flex items-center gap-3">
          <div className="w-10 h-10 flex items-center justify-center">
            <svg
              viewBox="0 0 48 48"
              className="w-full h-full text-white"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.4"
            >
              <circle cx="24" cy="24" r="21" />
              <g fill="#E07B30">
                <rect x="13" y="29" width="4.4" height="7" rx="1" />
                <rect x="19.8" y="25" width="4.4" height="11" rx="1" />
                <rect x="26.6" y="20" width="4.4" height="16" rx="1" />
                <rect x="33.4" y="15" width="4.4" height="21" rx="1" />
              </g>
            </svg>
          </div>
          <div className="flex flex-col">
            <span className="font-bold text-lg tracking-wide">
              YETI<span className="text-[#E07B30]">·</span>BI
            </span>
            <span className="text-xs font-mono tracking-widest text-gray-400 uppercase">
              Data &amp; Analytics
            </span>
          </div>
        </Link>

        {/* Desktop Nav Links */}
        <div className="hidden md:flex items-center gap-8">
          {navLinks.map((link) => (
            <a
              key={link.href}
              href={link.href}
              className="text-sm text-gray-300 font-medium hover:text-white transition-colors relative group"
            >
              {link.label}
              <span className="absolute bottom-0 left-0 w-0 h-0.5 bg-[#E07B30] group-hover:w-full transition-all duration-300" />
            </a>
          ))}
        </div>

        {/* CTA + Mobile Menu */}
        <div className="flex items-center gap-4">
          <a
            href="#agenda"
            className="hidden md:inline-flex px-6 py-2 bg-[#E07B30] text-[#2E2640] font-bold rounded-full text-sm hover:bg-[#C45F15] transition-colors"
          >
            Agenda tu diagnóstico
          </a>

          {/* Hamburger */}
          <button
            onClick={() => setMenuOpen(!menuOpen)}
            className="md:hidden w-10 h-10 flex items-center justify-center"
            aria-label="Abrir menú"
          >
            <div className="flex flex-col gap-1.5">
              <span
                className={`w-6 h-0.5 bg-white transition-all ${
                  menuOpen ? 'rotate-45 translate-y-2' : ''
                }`}
              />
              <span
                className={`w-6 h-0.5 bg-white transition-all ${
                  menuOpen ? 'opacity-0' : ''
                }`}
              />
              <span
                className={`w-6 h-0.5 bg-white transition-all ${
                  menuOpen ? '-rotate-45 -translate-y-2' : ''
                }`}
              />
            </div>
          </button>
        </div>
      </nav>

      {/* Mobile Menu */}
      {menuOpen && (
        <motion.div
          initial={{ opacity: 0, x: 400 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: 400 }}
          transition={{ type: 'spring', stiffness: 300, damping: 30 }}
          className="fixed inset-0 top-16 z-40 bg-[#221B31] md:hidden flex flex-col gap-2 px-6 py-8"
        >
          {navLinks.map((link) => (
            <a
              key={link.href}
              href={link.href}
              onClick={() => setMenuOpen(false)}
              className="text-xl font-serif italic text-gray-300 hover:text-white py-3 border-b border-white/10 transition-colors"
            >
              {link.label}
            </a>
          ))}
          <a
            href="#agenda"
            onClick={() => setMenuOpen(false)}
            className="mt-6 px-6 py-3 bg-[#E07B30] text-[#2E2640] font-bold rounded-full text-center"
          >
            Agenda tu diagnóstico
          </a>
        </motion.div>
      )}
    </>
  )
}
