'use client'

import { motion, useInView } from 'motion/react'
import { useRef } from 'react'
import { fadeUp, scaleIn, staggerContainer, revealViewport, motionTokens } from '@/lib/motion'

const technologies = [
  'Power BI',
  'Power Apps',
  'Power Automate',
  'Power Query',
  'SQL Server',
  'Microsoft Azure',
  'Python',
  'Microsoft Fabric',
]

export function Technologies() {
  const containerRef = useRef(null)
  const isInView = useInView(containerRef, { once: true, amount: 0.25 })

  return (
    <section id="tecnologias" className="bg-[#221B31] py-16 md:py-24">
      <div className="max-w-6xl mx-auto px-6 md:px-8">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: motionTokens.distance.md }}
          animate={isInView ? { opacity: 1, y: 0 } : { opacity: 0, y: motionTokens.distance.md }}
          transition={{
            duration: motionTokens.duration.base,
            ease: motionTokens.ease.out,
          }}
          className="max-w-2xl mb-12"
        >
          <div className="inline-flex items-center gap-3 mb-6">
            <span className="w-8 h-0.5 bg-[#E07B30]" />
            <span className="font-mono text-xs font-bold uppercase tracking-widest text-[#E07B30]">
              Stack tecnológico
            </span>
          </div>
          <h2 className="font-serif text-4xl md:text-5xl font-bold leading-tight">
            Las herramientas que <em className="italic text-[#E07B30]">dominamos</em>.
          </h2>
        </motion.div>

        {/* Tech Grid */}
        <motion.div
          ref={containerRef}
          className="grid grid-cols-2 md:grid-cols-4 gap-px bg-white/10 rounded-2xl overflow-hidden border border-white/10"
          initial="hidden"
          animate={isInView ? 'show' : 'hidden'}
          variants={staggerContainer(motionTokens.stagger.tight, 0.1)}
          viewport={revealViewport}
        >
          {technologies.map((tech, idx) => (
            <motion.div
              key={idx}
              variants={scaleIn}
              className="bg-[#2E2640] px-6 py-8 md:py-10 flex items-center justify-center text-center hover:bg-[#372E4D] transition-colors duration-300"
            >
              <span className="font-sans font-semibold text-base md:text-lg text-gray-300 hover:text-white transition-colors">
                {tech.split(' ').length > 1 ? (
                  <>
                    {tech.split(' ')[0]}
                    <span className="text-[#E07B30]"> </span>
                    {tech.split(' ')[1]}
                  </>
                ) : (
                  tech
                )}
              </span>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  )
}
