'use client'

import { motion, useInView } from 'motion/react'
import { useRef } from 'react'
import { useCountUp, motionTokens, fadeUp } from '@/lib/motion'

function StatCard({
  number,
  suffix,
  label,
  decimals,
  delay,
}: {
  number: number
  suffix: string
  label: string
  decimals?: number
  delay: number
}) {
  const { ref, display } = useCountUp(number, {
    suffix,
    decimals: decimals || 0,
    duration: 1.3,
  })

  const containerRef = useRef(null)
  const isInView = useInView(containerRef, { once: true, amount: 0.4 })

  return (
    <motion.div
      ref={containerRef}
      initial={{ opacity: 0, y: motionTokens.distance.md }}
      animate={isInView ? { opacity: 1, y: 0 } : { opacity: 0, y: motionTokens.distance.md }}
      transition={{
        duration: motionTokens.duration.base,
        ease: motionTokens.ease.out,
        delay: delay * motionTokens.stagger.tight,
      }}
      className="flex flex-col items-center md:items-start gap-3 py-10 md:py-14 px-4 md:px-6 border-l border-white/10 first:border-l-0"
    >
      <div className="flex items-baseline gap-1 justify-center md:justify-start font-serif text-4xl md:text-6xl lg:text-7xl font-bold">
        <span ref={ref} className="text-white">
          {display}
        </span>
      </div>
      <div className="font-mono text-xs md:text-sm tracking-widest uppercase text-gray-400 text-center md:text-left">
        {label}
      </div>
    </motion.div>
  )
}

export function Stats() {
  const stats = [
    { number: 37, suffix: '%', label: 'Reducción de tiempos\noperativos' },
    { number: 1.2, suffix: ' B COP', label: 'Recuperados en\nfugas de valor', decimals: 1 },
    { number: 40, suffix: '+', label: 'Proyectos de mejora\nentregados' },
    { number: 8, suffix: '', label: 'Años de experiencia\nen operación' },
  ]

  return (
    <section className="border-t border-b border-white/10 bg-[#221B31]">
      <div className="max-w-6xl mx-auto">
        <div className="grid grid-cols-2 md:grid-cols-4">
          {stats.map((stat, index) => (
            <StatCard
              key={index}
              number={stat.number}
              suffix={stat.suffix}
              label={stat.label}
              decimals={stat.decimals}
              delay={index}
            />
          ))}
        </div>
      </div>
    </section>
  )
}
